async function* backend() {
  for (const t of ["思考中…", "检索知识库", "生成：你好", "，我是助手"]) {
    await new Promise(r => setTimeout(r, 5));
    yield `data: ${t}\n\n`;
  }
}
async function gateway(src, sink) {
  for await (const c of src) sink.push(c); // 收到一块立刻转发一块
}
(async () => {
  const out = [];
  await gateway(backend(), out);
  const events = out.join("").split("\n\n").filter(Boolean).map(e => e.replace(/^data: /, ""));
  console.log("转发块数:", out.length);
  console.log("客户端拼接:", events.join(""));
})();
